mapper.select:
SELECT 
FROM transaction
WHERE user_seq = #{userSeq}
ORDER BY seq DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM transaction
WHERE user_seq = #{userSeq}

SELECT 
FROM transaction
WHERE user_seq = #{userSeq}
  AND reg_date BETWEEN #{startDate} AND #{endDate}
ORDER BY seq DESC

SELECT 
FROM transaction
WHERE user_seq = #{userSeq}
  AND tx_type = #{txType}
ORDER BY seq DESC
LIMIT #{offset}, #{limit}

SELECT 
FROM transaction


        AND tx_type = #{txType}


ORDER BY seq DESC
LIMIT #{limit}

SELECT DATE(reg_date) AS statDate, tx_type AS txType, currency_type AS currencyType, COUNT(*) AS transactionCount, SUM(amount) AS totalAmount FROM transaction WHERE user_seq = #{userSeq}
AND DATE(reg_date) >= #{startDate}
AND DATE(reg_date) <= #{endDate}
GROUP BY DATE(reg_date), tx_type, currency_type ORDER BY statDate DESC

SELECT DATE_FORMAT(reg_date, '%Y-%m') AS statMonth, tx_type AS txType, currency_type AS currencyType, COUNT(*) AS transactionCount, SUM(amount) AS totalAmount FROM transaction WHERE user_seq = #{userSeq}
AND DATE(reg_date) >= #{startDate}
AND DATE(reg_date) <= #{endDate}
GROUP BY statMonth, tx_type, currency_type ORDER BY statMonth DESC

SELECT COALESCE(service_id, 'ETC') AS serviceId, tx_type AS txType, COUNT(*) AS transactionCount, SUM(amount) AS totalAmount, SUM(quantity) AS totalQuantity FROM transaction WHERE tx_type = 'DEDUCT'
AND user_seq = #{userSeq}
AND user_seq IN
#{uid}
AND DATE(reg_date) >= #{startDate}
AND DATE(reg_date) <= #{endDate}
GROUP BY service_id, tx_type ORDER BY totalAmount DESC

SELECT COALESCE(SUM(CASE WHEN tx_type = 'CHARGE' THEN amount ELSE 0 END), 0) AS totalCharge, COALESCE(SUM(CASE WHEN tx_type = 'DEDUCT' THEN amount ELSE 0 END), 0) AS totalDeduct, COALESCE(SUM(CASE WHEN tx_type = 'REFUND' THEN amount ELSE 0 END), 0) AS totalRefund, COUNT(CASE WHEN tx_type = 'CHARGE' THEN 1 END) AS chargeCount, COUNT(CASE WHEN tx_type = 'DEDUCT' THEN 1 END) AS deductCount, COUNT(CASE WHEN tx_type = 'REFUND' THEN 1 END) AS refundCount FROM transaction WHERE 1=1
AND user_seq = #{userSeq}
AND user_seq IN
#{uid}
AND DATE(reg_date) >= #{startDate}
AND DATE(reg_date) <= #{endDate}

SELECT user_seq AS userSeq, tx_type AS txType, COUNT(*) AS transactionCount, SUM(amount) AS totalAmount FROM transaction WHERE user_seq IN
#{userSeq}
AND DATE(reg_date) >= #{startDate}
AND DATE(reg_date) <= #{endDate}
GROUP BY user_seq, tx_type ORDER BY user_seq, tx_type

SELECT t.user_seq AS userSeq, (SELECT COALESCE(SUM(w.balance), 0) FROM wallet w WHERE w.user_seq = t.user_seq) AS currentBalance, MAX(t.reg_date) AS lastTransactionDate FROM transaction t WHERE t.user_seq IN
#{userSeq}
GROUP BY t.user_seq

SELECT MAX(reg_date)
FROM transaction
WHERE user_seq = #{userSeq}
